// Datos reales de pelotas de fútbol.
//
// Primera carga (2026-09-17, mismo pedido/pipeline que gloves.ts -- ver
// ese archivo y scripts/gear-mining/mine_gear.py para el contexto
// completo). Todas las tiendas cobran en EUR.
//
// Filtro real por tienda: Foot-Store/Sport is Good (ES y FR) usan su
// taxonomía real "Football > Ballon de football > Adulte > ..."; Gigasport
// usa "Fußbälle > Matchbälle/Trainingsbälle"/"Ballons de football >
// Ballons de match/d'entraînement"; Deporte Outlet no tiene categoría
// confiable, filtro por título ("balón"+"fútbol") -- a diferencia de
// gloves.ts, NO se filtra por género/edad ahí: el 100% del catálogo real
// de pelotas de Deporte Outlet viene etiquetado "Niños" en su propio
// feed (custom_2) aunque incluya pelotas talla 5 estándar de partido
// (confirmado real, ej. "Zeus Beach Soccer Balón de fútbol..."), así que
// excluir por ese campo hubiera dejado esta tienda en cero.
//
// 2026-09-18 (reporte real del usuario): dos fixes de calidad de datos
// -- (1) Deporte Outlet dejaba pasar memorabilia de coleccionista
// (marca SIGNABLES, "Balón de fútbol Artículo de coleccionista 14 cm",
// no es una pelota para jugar) porque el filtro por título no la
// excluía; (2) igual que en gloves.ts, mine_gear.py ahora funde el
// mismo producto real vendido en varias tiendas espejo en UNA sola
// BallProduct con varias BallOffer. Ver COLLECTIBLE_RE y
// merge_by_model() en mine_gear.py.
export interface BallOffer {
  store:
    | "FootStoreES"
    | "SportIsGoodES"
    | "FootStoreFR"
    | "SportIsGoodFR"
    | "DeporteOutlet"
    | "GigasportDE"
    | "GigasportCH"
    | "GigasportFR";
  price: number;
  priceMax?: number;
  shipping: number;
  currency: "EUR";
  url: string;
  imageUrl: string;
  sizes: string[];
  sizePrices?: { size: string; price: number; url: string }[];
}

export interface BallProduct {
  id: string;
  brand: string;
  model: string;
  // Color real del feed -- ver el comentario equivalente en
  // GloveProduct.colour (gloves.ts), mismo motivo.
  colour: string;
  offers: BallOffer[];
}

